mod pricing;

use pricing::delivery_quote;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let distance: i64 = lines.next().unwrap().parse().unwrap();
    let base: i64 = lines.next().unwrap().parse().unwrap();
    let per_km: i64 = lines.next().unwrap().parse().unwrap();
    let service = lines.next().unwrap();
    let amount = delivery_quote(distance, base, per_km, service);
    println!("quote={amount}|service={service}");
}

pub fn delivery_quote(distance: i64, base: i64, per_km: i64, service: &str) -> i64 {
    let express_fee = if service == "express" { 300 } else { 0 };
    let long_distance_fee = if distance > 100 { 500 } else { 0 };
    base + distance * per_km + express_fee + long_distance_fee
}

