use pricing::delivery_quote;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let distance: u64 = lines.next().unwrap().parse().unwrap();
    let base: u64 = lines.next().unwrap().parse().unwrap();
    let per_km: u64 = lines.next().unwrap().parse().unwrap();
    let service = lines.next().unwrap();
    let amount = delivery_quote(distance, base, per_km, service);
    println!("quote={amount}|service={service}");
}

pub fn delivery_quote(distance: u64, base: u64, per_km: u64, service: &str) -> u64 {
    let service_fee = if service == "express" { 300 } else { 0 };
    let long_distance_fee = if distance > 100 { 500 } else { 0 };
    base + distance * per_km + service_fee + long_distance_fee
}

